#include <stdlib.h>

typedef struct { void *state; } acc_t;

typedef acc_t *(*combine_fn)(void *a, void *b);
typedef acc_t *(*identity_fn)(void *);

/* sum: identity 0, combine + */
static acc_t sum_id(void)  { acc_t *a = malloc(sizeof *a); a->state = calloc(1, sizeof(long)); return a; }
static acc_t *sum_add(void *x, void *y) { *(long *)((acc_t *)x)->state += *(long *)((acc_t *)y)->state; return x; }

/* the one generic fold, written once, used by every instance */
void fold(const void *base, size_t n, size_t stride,
          identity_fn id, combine_fn op) {
    acc_t *acc = id();
    for (size_t i = 0; i < n; i++) acc = op(acc, (const char *)base + i * stride);
    /* acc holds the aggregate */
}
